import csv
import json
import os
from decimal import Decimal
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126", "20190127", "20190128", "20190129"]
targets = [("石家庄站", "永清站"), ("南京站", "南通站")]
lines = ["陕京二线", "冀宁线"]

result = {}
for line in lines:
    result[line] = {}
    for date in dates:
        path = DIR / f"{date}_pipeline.csv"
        with path.open("r", encoding="utf-8-sig", newline="") as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row["管道划分"] != line:
                    continue
                key = (row["起点站名"], row["终点站名"])
                if key in targets:
                    result[line].setdefault(date, {})
                    result[line][date][f"{key[0]}—{key[1]}"] = Decimal(row["管道流量"])

summary = {}
for line in lines:
    totals = {}
    for date in dates:
        day_total = sum(result[line].get(date, {}).values())
        totals[date] = day_total
    summary[line] = {
        "daily_totals": totals,
        "window_total": sum(totals.values()),
    }

diff = abs(summary["陕京二线"]["window_total"] - summary["冀宁线"]["window_total"])
higher = "陕京二线" if summary["陕京二线"]["window_total"] > summary["冀宁线"]["window_total"] else "冀宁线"
payload = {
    "window": {"start": "2019-01-25", "end": "2019-01-29"},
    "segments": ["石家庄站—永清站", "南京站—南通站"],
    "detail": summary,
    "higher_line": higher,
    "difference": diff,
}
print(json.dumps(payload, ensure_ascii=False, indent=2, default=str))

